mapper.select:
select * from ( SELECT T1.ISSUE_AMT ISSUE_AMT,
,T2.TYPE_6
,T2.TYPE_9 ,T2.TYPE_10 ,T2.TYPE_11 ,T2.TYPE_12
,T4.RATE*100 RATE ,T5.BASIS
,T4.INT_TYPE ,T6.CUSTOMER_NAME financierName ,T7.CUSTOMER_NAME sponsorName,
FPR.recommender recommender, FPR.recommenderName recommenderName,
T1.FINANCIER,T1.SPONSOR FROM FIN_PRODUCT T1
LEFT JOIN ( SELECT FPR.FINPROD_ID, listagg(FPR.RECOMMENDER,'，') within group(order by FPR.RECOMMENDER) recommender, listagg(MCP.COUNTER_NAME,'，') within group(order by FPR.RECOMMENDER) recommenderName FROM FIN_PRODUCT_RECOMMENT FPR LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID GROUP BY FPR.FINPROD_ID ) FPR ON FPR.FINPROD_ID = T1.FINPROD_ID
left join FIN_PRODUCT_TYPE T2 ON T2.FINPROD_ID = T1.FINPROD_ID left join FIN_CASH_INFO T3 ON T3.FINPROD_ID = T1.FINPROD_ID
AND T3.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND T3.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
left join FIN_RATE_INFO T4 ON T4.CASH_ID = T3.CASH_ID AND T4.EFF_DATE = T1.VDATE LEFT JOIN FIN_CASH_CALC_RULE T5 ON T5.CASH_ID = T3.CASH_ID and T5.EFF_DATE = T1.VDATE LEFT JOIN MST_CUSTOMER_INFO T6 ON T6.CUSTOMER_ID = T1.FINANCIER LEFT JOIN MST_CUSTOMER_INFO T7 ON T7.CUSTOMER_ID = T1.SPONSOR )T
AND (T.FINPROD_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%') or T.FINPROD_NAME like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%'))
AND T.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T.CCY = #{ccy,jdbcType=VARCHAR}
AND T.TYPE_6 in
#{item}
AND T.TYPE_9 in
#{item}
AND T.TYPE_10 in
#{item}
AND T.TYPE_11 in
#{item}
AND T.TYPE_12 in
#{item}
AND T.VDATE >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND T.VDATE <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND T.MDATE >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND T.MDATE <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
AND T.FINANCIER = #{financier,jdbcType=VARCHAR}
AND T.SPONSOR = #{sponsor,jdbcType=VARCHAR}

SELECT T1.ISSUE_AMT ISSUE_AMT,
,T3.TYPE_6, T3.TYPE_7,
T3.TYPE_9, T3.TYPE_10, T3.TYPE_11, T3.TYPE_12,
T4.ASSET_SOURCE, T4.ASSET_PROVIDER, T4.ASSET_SOURCE_UNIT, T4.LOAD_BANK, T4.SETTLE_DAYS, t2.INVEST_NATURE, T4.PROJ_INVEST_INDUSTRY, T4.PROJ_INVEST_INDUSTRY2, T4.CASH_OUT_NO CASH_OUT_NO, T5.BUYOUT_RATE*100 BUYOUT_RATE, T.PFLSH pflsh, T.HAP_CREDIT_AMT hapCreditAmt, T.CREDIT_FLAG creditFlag, T4.ACTUAL_CREDIT_PROVID actualCreditProvid, T1.FINANCIER financier, T1.SPONSOR sponsor, T6.REP_ASSET_TYPE, T4.TRIAL_NO, T1.CONTRACT_NO, T1.INVEST_ADVISER, T2.IS_INNER_ADV FROM FIN_PRODUCT T1 LEFT JOIN ( SELECT B.FINPROD_ID, A.CREDIT_FLAG, A.PFLSH, A.HAP_CREDIT_AMT , A.CUSTOMER_ID FROM (select t.CREDIT_FLAG,t.PFLSH,t.HAP_CREDIT_AMT, t.CUSTOMER_ID, ROW_NUMBER() over (partition by t.CUSTOMER_ID order by t.VDATE desc) RN from CREDIT_LINES t) A LEFT JOIN CREDIT_ASSETPOOL_DETAIL B ON B.SEQNO = A.CUSTOMER_ID where A.RN = 1 ) T ON (T.FINPROD_ID = T1.FINPROD_ID OR T.CUSTOMER_ID = T1.FINPROD_ID) LEFT JOIN FIN_PRODUCT_ADD T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T3 ON T3.FINPROD_ID = T1.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT_BUYOUT_RATE T5 ON T5.FINPROD_ID = T1.FINPROD_ID AND T5.EFF_DATE = T1.VDATE LEFT JOIN REP_ASSET_DEPT T6 on T1.FINPROD_ID = T6.REP_FINPROD_ID
T1.FINPROD_ID = #{finprodId}
T1.FINPROD_MARKET_ID = #{finprodMarketId}

SELECT T1.CASH_OUT_NO ,T1.REL_CONTRACT_NO ,T1.IS_GOV ,T1.IS_HIGH_POLLUTION ,T1.IS_GOVT_LIMIT ,T1.IS_GOVT_NEW_STRATEGY ,T1.FUND_USE_TYPE ,T1.REPAYMENT_TYPE ,T1.BUSI_CONTRACT_PROD ,T1.IS_LOW_RISK ,T1.APPROVE_NO ,T1.CREDIT_TYPE ,T1.APROVE_AMOUNT ,T1.APROVE_LIMIT ,T1.LAST_APROVE_INS ,T1.USED_AMOUNT ,T1.SIGN_DATE ,T1.RISK_TYPE ,T1.ASSURE_PATTERN ,T1.ASSURE_MARK ,T1.BRANCH_INS_NO ,T1.BECIF ,T1.CREDIT_CUSTOMER_NO ,T1.CREDIT_CUSTOMER_NAME ,T1.CREDIT_BUSINESS_NO ,T1.CREDIT_BUSINESS_NAME ,T1.BUSI_CONTRACT_NO ,T1.VDATE ,T1.MDATE ,T1.YIELD ,T1.PAYMENT_AMOUNT ,T2.CUSTOMER_ID ,T2.INSTITUTION_NAME ,T2.PARTY_TYPE3 ,T2.REP_INDUSTRY ,T2.REP_INDUSTRY_LEVEL2 ,T2.PARTY_TYPE2 ,T2.PARTY_TYPE1 ,T2.IS_TOP_COMPANY ,T2.INSTITUTION_CODE ,T2.IS_GOV
,T2.PROVINCE ,T2.CITY ,T2.COUNTY ,T2.HOLDING_TYPE ,T2.CUSTOMER_OBJ_TYPE ,T2.IS_LISTED_COMPANY ,T2.IS_GROUP_CUSTOMER ,T2.PARENT_CUSTOMER_ID ,T2.PARENT_CUSTOMER_NAME ,T2.IS_PRIVATE ,T2.IS_ESCAPE_DEPT ,T2.CREDIT_TYPE CREDIT_TYPE1 ,T2.IS_CREDIT_RELATED_TRD ,T2.STRUCT_ADJUST_TYPE ,T2.INDUS_UPGRATE_TYPE ,T2.BUSI_SCOPE ,T2.MAIN_BUSI ,T2.REGIST_CAPITAL ,T2.ACTUAL_CAPITAL ,T2.CUSTOMER_LEVEL ,T3.GRADE_ORG_ID ,T3.GRADE_TYPE ,T3.GRADE_RESULT ,T3.GRADE_RPT_YEAR ,T3.GRADE_MODEL_TYPE ,T3.GRADE_EFF_DATE ,T3.GRADE_END_DATE FROM INTERF_CREDIT_ITEM_INFO T1 LEFT JOIN INTERF_CMS_INSTITUTION T2 ON T2.CUSTOMER_ID = T1.CREDIT_CUSTOMER_NO LEFT JOIN INTERF_CMS_INSTITUTION_GRADE T3 ON T3.GRADE_ORG_ID = T1.CREDIT_CUSTOMER_NO
T1.CASH_OUT_NO = #{cashOutNo}
